import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Module: ops::derive","description":"","frontmatter":{},"headers":[],"relativePath":"api/host-tensor/handl_host_tensor/ops/derive.md","filePath":"api/host-tensor/handl_host_tensor/ops/derive.md"}`),a={name:`api/host-tensor/handl_host_tensor/ops/derive.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><strong>handl_host_tensor &gt; ops &gt; derive</strong></p><h1 id="module-ops-derive" tabindex="-1">Module: ops::derive <a class="header-anchor" href="#module-ops-derive" aria-label="Permalink to “Module: ops::derive”">​</a></h1><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to “Contents”">​</a></h2><p><strong>Structs</strong></p><ul><li><a href="#derive"><code>Derive</code></a> - The Rust handl for <code>op &quot;tensor.derive&quot; : String -&gt; Value</code>.</li></ul><p><strong>Constants</strong></p><ul><li><a href="#deriv-pairs"><code>DERIV_PAIRS</code></a> - Forward op name → registered adjoint op name, the table</li></ul><hr><h2 id="handl-host-tensor-ops-derive-deriv-pairs" tabindex="-1">handl_host_tensor::ops::derive::DERIV_PAIRS <a class="header-anchor" href="#handl-host-tensor-ops-derive-deriv-pairs" aria-label="Permalink to “handl_host_tensor::ops::derive::DERIV_PAIRS”">​</a></h2><p><em>Constant</em>: <code>&amp;[(&amp;str, &amp;str)]</code></p><p>Forward op name → registered adjoint op name, the table <code>tensor.derive</code> reads. A pair is only listed when the adjoint impl exists in [<code>tensor_op_registry</code>], so <code>derive</code>&#39;s result always resolves through <code>ModuleLookup::lookup</code> on the same module — a <code>.hnl</code> optimization loop can call the returned name sight unseen.</p><h2 id="handl-host-tensor-ops-derive-derive" tabindex="-1">handl_host_tensor::ops::derive::Derive <a class="header-anchor" href="#handl-host-tensor-ops-derive-derive" aria-label="Permalink to “handl_host_tensor::ops::derive::Derive”">​</a></h2><p><em>Struct</em></p><p>The Rust handl for <code>op &quot;tensor.derive&quot; : String -&gt; Value</code>.</p><p>Returns the qualified op name of the adjoint registered for <code>name</code> in [<code>DERIV_PAIRS</code>], or <code>null</code> when no pair exists. <code>name</code> may be qualified (<code>&quot;tensor.batch_norm&quot;</code>) or a bare local name (<code>&quot;batch_norm&quot;</code> → <code>&quot;tensor.batch_norm&quot;</code>). The result resolves through <code>ModuleLookup::lookup</code> on the same registry, so an optimization-loop consumer can dispatch it directly.</p><p>This is a <em>registered-pairs</em> table, not autodiff: a <code>.hnl</code> function name gets <code>null</code> — a host <code>Function</code> sees only evaluated argument values, so deriving an adjoint for <code>.hnl</code> source would need a source-level transform or a reverse-mode tape in the eval engine (README follow-up).</p><p><strong>Unit Struct</strong></p><p><strong>Traits:</strong> Copy</p><p><strong>Trait Implementations:</strong></p><ul><li><strong>Clone</strong><ul><li><code>fn clone(self: &amp;Self) -&gt; Self</code></li></ul></li><li><strong>Debug</strong><ul><li><code>fn fmt(self: &amp;Self, f: &amp; mut $crate::fmt::Formatter) -&gt; $crate::fmt::Result</code></li></ul></li><li><strong>Function</strong><ul><li><code>fn call(self: &amp;Self, args: &amp;[Value], _ctx: &amp; mut EvalContext) -&gt; Result&lt;Value, EvalError&gt;</code></li></ul></li></ul>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};